export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  return rows.map((row) => row.slug);
}
/**
 * Extracts `@handle` mentions from comment bodies and resolves them to member
 * ids.
 *
 * A handle is the local part of a member's email address, lowercased — that
 * is what the comment composer autocompletes and what `CommentService` feeds
 * to the notification fan-out, so extraction and resolution must agree
 * exactly. Mentions inside code spans and fenced blocks are ignored.
 */
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";

/** `@` must start the line or follow whitespace/punctuation, never an email. */
const MENTION_PATTERN = /(^|[\s(<[])@([a-z0-9][a-z0-9._-]{0,38}[a-z0-9])/gi;

function withoutCode(body: string): string {
  return body.replace(/```[\s\S]*?```/g, " ").replace(/`[^`]*`/g, " ");
}

/** The handle Taskflow addresses a member by, derived from their email. */
export function handleOf(member: MemberWithUser): string {
  return (member.user.email.split("@")[0] ?? "").toLowerCase();
}

/** Every distinct handle mentioned, in first-appearance order. */
export function extractMentions(body: string): readonly string[] {
  const seen = new Set<string>();
  const handles: string[] = [];

  for (const match of withoutCode(body).matchAll(MENTION_PATTERN)) {
    const handle = (match[2] ?? "").toLowerCase();
    if (handle === "" || seen.has(handle)) continue;
    seen.add(handle);
    handles.push(handle);
  }

  return handles;
}

/**
 * Maps the mentions in `body` onto the ids of members who actually exist in
 * the organization. Unknown handles are silently dropped — a typo must never
 * fail the comment write.
 */
export function resolveMentions(
  body: string,
  members: readonly MemberWithUser[],
): readonly UserId[] {
  const byHandle = new Map<string, UserId>();
  for (const member of members) {
    byHandle.set(handleOf(member), member.userId);
  }

  const resolved: UserId[] = [];
  const seen = new Set<UserId>();
  for (const handle of extractMentions(body)) {
    const userId = byHandle.get(handle);
    if (userId === undefined || seen.has(userId)) continue;
    seen.add(userId);
    resolved.push(userId);
  }

  return resolved;
}

/** Wraps every mention in a span so the comment renderer can style it. */
export function highlightMentions(body: string): string {
  return body.replace(
    MENTION_PATTERN,
    (_match, prefix: string, handle: string) =>
      `${prefix}<span class="mention">@${handle}</span>`,
  );
}
/**
 * Builds the daily digest bundle per recipient from unread notifications inside the org's digest window.
 *
 * Must call (do not reimplement): isEnabled, renderEmail
 */
import { isEnabled } from "@/lib/feature-flags";
import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { renderEmail } from "./email-service";
import { buildFlagContext } from "./feature-flag-service";
import type { RenderedEmail } from "@/server/services/email-service";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { User } from "@/types/member";
import type { DigestBundle, DigestEntry } from "@/types/notification";

/** A digest with fewer entries than this is not worth an email. */
const MIN_ENTRIES = 1;

/**
 * Collects one recipient's unread notifications inside the window. Returns
 * `null` — rather than an empty bundle — when the org's plan does not include
 * the digest, or when there is nothing to say: the caller treats `null` as
 * "send nothing", so a quiet day produces no mail at all.
 */
export async function buildDigest(
  orgId: OrgId,
  recipientId: UserId,
  windowStart: IsoTimestamp,
  windowEnd: IsoTimestamp,
): Promise<DigestBundle | null> {
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return null;

  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;

  const unread = await notificationRepo.listUnreadSince(
    orgId,
    recipientId,
    windowStart,
  );

  const entries: DigestEntry[] = unread
    .filter((notification) => notification.createdAt <= windowEnd)
    .map((notification) => ({
      notificationId: notification.id,
      kind: notification.kind,
      title: notification.title,
      href: notification.href,
      occurredAt: notification.createdAt,
    }))
    .slice(0, DIGEST_MAX_ENTRIES);

  if (entries.length < MIN_ENTRIES) return null;

  return { orgId, recipientId, entries, windowStart, windowEnd };
}

/**
 * Who gets a digest: everyone who set at least one notification kind to
 * `digestOnly`. Opting into the digest is what suppresses the immediate
 * emails, so the two lists are two views of the same preference.
 */
export async function listDigestRecipients(
  orgId: OrgId,
): Promise<readonly UserId[]> {
  return preferenceRepo.listDigestSubscribers(orgId);
}

/** Renders one bundle through the shared email pipeline. */
export async function renderDigest(
  bundle: DigestBundle,
  recipient: User,
): Promise<RenderedEmail> {
  return renderEmail("digest", {
    orgId: bundle.orgId,
    recipientName: recipient.name,
    entryCount: bundle.entries.length,
    windowStart: bundle.windowStart,
    windowEnd: bundle.windowEnd,
    headline: bundle.entries[0]?.title ?? "",
  });
}
import type {
  IsoTimestamp,
  MemberId,
  OrgId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
  InvitationId,
} from "./common";

/**
 * Taskflow RBAC roles, ordered from most to least privileged. `ROLE_RANK`
 * below is the single source of truth for "at least this role" comparisons —
 * never compare role strings directly.
 */
export type Role = "owner" | "admin" | "member" | "viewer";

export const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

export const ROLE_RANK: Readonly<Record<Role, number>> = {
  owner: 4,
  admin: 3,
  member: 2,
  viewer: 1,
};

export type MemberStatus = "active" | "invited" | "suspended";

export interface User extends Timestamps {
  readonly id: UserId;
  readonly email: string;
  readonly name: string;
  readonly avatarUrl: string | null;
  readonly timezone: string;
  readonly emailVerifiedAt: IsoTimestamp | null;
}

export interface Member extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: MemberId;
  readonly userId: UserId;
  readonly role: Role;
  readonly status: MemberStatus;
  readonly invitedBy: UserId | null;
  readonly joinedAt: IsoTimestamp | null;
  readonly lastSeenAt: IsoTimestamp | null;
}

/** A member joined with the user record it points at, for list UIs. */
export interface MemberWithUser extends Member {
  readonly user: User;
}

export interface Invitation extends Timestamps, TenantScoped {
  readonly id: InvitationId;
  readonly email: string;
  readonly role: Role;
  readonly invitedBy: UserId;
  readonly token: string;
  readonly expiresAt: IsoTimestamp;
  readonly acceptedAt: IsoTimestamp | null;
  readonly revokedAt: IsoTimestamp | null;
}

/**
 * The authenticated principal for one request, always resolved for exactly one
 * organization. Everything that authorizes a mutation takes an `Actor` — see
 * `can()` in `src/lib/permissions.ts` and `assertOrgScope()` in
 * `src/lib/tenant.ts`.
 */
export interface Actor {
  readonly userId: UserId;
  readonly orgId: OrgId;
  readonly role: Role;
  /** Staff impersonation / internal tooling escape hatch. Defaults to false. */
  readonly isPlatformStaff?: boolean;
}

export interface SessionPrincipal {
  readonly userId: UserId;
  readonly email: string;
  readonly activeOrgId: OrgId | null;
  readonly expiresAt: IsoTimestamp;
}

/** True when `role` is at least as privileged as `atLeast`. */
export function hasRoleAtLeast(role: Role, atLeast: Role): boolean {
  return ROLE_RANK[role] >= ROLE_RANK[atLeast];
}

