export class MemberSuspendedError extends Error {
  readonly code = \"conflict\";
  constructor() {
    super(\"Work cannot be assigned to a suspended member\");
    this.name = \"MemberSuspendedError\";
  }
}

async function changeMemberStatus(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
  status: \"active\" | \"suspended\",
): Promise<Member> {
  assertOrgScope(actor, input.orgId);
  const found = await memberRepo.findMemberById(input.orgId, input.memberId);
  const member = requireFound(
    found && found.archivedAt === null ? found : null,
    \"Member\", input.memberId,
  );
  assertCan(actor, \"member:remove\", memberResource(member));
  if (member.userId === actor.userId) {
    throw new Error(\"Cannot suspend or reinstate yourself\");
  }
  if ("'!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error("Cannot suspend or reinstate a member whose role outranks yours");
  }
  if (member.status === status) return member;
  if (status === "suspended") {
    await assertLastOwnerRetained(input.orgId, input.memberId, "member");
  }
  const updated = await memberRepo.updateMemberStatus(input.orgId, input.memberId, status);
  await emit(status === "suspended" ? "member.suspended" : "member.reinstated", {
    ...actorEnvelope(actor), memberId: updated.id, userId: updated.userId,
  });
  return updated;
}

export async function suspendMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  return changeMemberStatus(actor, input, "suspended");
}

export async function reinstateMember(
  actor: Actor,
  input: { orgId: OrgId; memberId: MemberId },
): Promise<Member> {
  return changeMemberStatus(actor, input, "active");
}
